for (const item of $input.all()) {
  let text = item.json.output || '';

  // Elimina backticks, "json", saltos de línea, y espacios extra
  let clean = text
    .replace(/```/g, '')            // Elimina todos los backticks
    .replace(/json/gi, '')          // Elimina la palabra "json" (case-insensitive)
    .replace(/\\n/g, '')            // Elimina los "\n" literales (barra + n)
    .replace(/\s+/g, ' ')           // Convierte múltiples espacios en uno
    .trim();

  try {
    const data = JSON.parse(clean);
    item.json.cantidadConsultas = data.cantidadConsultas || 0;
    item.json.tipoNegocio = (data.tipoNegocio || '').trim();
  } catch (e) {
    item.json.cantidadConsultas = 0;
    item.json.tipoNegocio = '';
  }
}

return $input.all();
